const venuePhotos={},venueLayouts={},venueSpaces={};let venueRegion='all';

let venueSearch='',includeDemoVenues=false;
const showcaseVenues=[{id:'showcase-garden',name:'גני אור · אולם לדוגמה',city:'השרון',region:'שרון',address:'מתחם דמיוני להמחשה',showcase:true,imageUrl:'demo-garden.png',description:'גן אירועים בסגנון ים־תיכוני עם קבלת פנים פתוחה, צמחייה טבעית ואווירה אלגנטית.',spaces:[{name:'הגן הגדול',capacity:600},{name:'האולם האינטימי',capacity:180}]},{id:'showcase-palace',name:'ארמון הזהב · אולם לדוגמה',city:'המרכז',region:'מרכז',address:'מתחם דמיוני להמחשה',showcase:true,imageUrl:'demo-palace.png',description:'אולם ערב יוקרתי עם נברשות, עיצוב בגוני שמפניה ושני חללים לאירועים בגדלים שונים.',spaces:[{name:'אולם המלכות',capacity:800},{name:'אולם הבוטיק',capacity:250}]}];
function directoryVenues(){return [...showcaseVenues,...(typeof publicVenueCatalog==='undefined'?[]:publicVenueCatalog),...(includeDemoVenues?providerVenues.map(v=>({...v,demo:true})):[])];}
function venueDirectoryCard(v){const full=v.showcase===true||(v.subscriber===true&&v.partnerVerified===true&&!v.demo),photo=full?venuePhotos[v.id]||v.imageUrl:null;const brand=document.querySelector('.brand')?.innerHTML||'<span class="brand-name">BESTEVENT</span>';return '<article class="venue-directory-card'+(full?' venue-partner-card':'')+'">'+(photo?'<img class="venue-photo" src="'+esc(photo)+'" alt="'+esc(v.name)+'">':'<div class="venue-brand-placeholder" aria-label="BESTEVENT"><div class="venue-brand-lockup">'+brand+'</div><span>הרגעים שלכם מתחילים כאן</span></div>')+'<div class="venue-directory-details"><span class="provider-ad">'+(v.showcase?'שותף לדוגמה · המחשה בלבד':v.demo?'נתוני הדגמה':full?'אולם שותף · BESTEVENT':'כרטיס בסיסי')+'</span><h3>'+esc(v.name)+'</h3><p>'+esc(v.city||v.region)+' · '+esc(v.region)+'</p><p>'+esc(v.address||'כתובת מדויקת לא פורסמה במקור שנבדק')+'</p>'+(v.showcase?'<p class="venue-demo-notice">אולם דמיוני · תמונות המחשה שנוצרו במיוחד לדוגמה</p><p>'+esc(v.description)+'</p>':'')+(v.phone?supplierPhoneMarkup(v.phone):v.showcase?'':'<p class="muted">טלפון לא פורסם במקור שנבדק</p>')+(full||v.demo?(v.demo?venueLayoutCard(v):'<section class="venue-capacity-summary"><h4>חללים וקיבולת</h4>'+((v.spaces||[]).map(space=>'<div><span>'+esc(space.name)+'</span><strong>'+(space.capacity?'עד '+space.capacity+' אורחים':'קיבולת לבירור')+'</strong></div>').join('')||'<p class="muted">חללים וקיבולות לא פורסמו במקור שנבדק.</p>')+(v.capacityNote?'<p class="muted">'+esc(v.capacityNote)+'</p>':'')+(v.showcase?'<small>חללים וקיבולות להמחשה בלבד. אין הזמנה או שותפות אמיתית.</small>':'<small>פרטי המקור נבדקו ב־31.10.2026. יש לאשר התאמה, זמינות וקיבולת מול האולם.</small>')+'</section>'):'')+(v.sourceUrl?'<a class="secondary venue-official-link" href="'+esc(v.sourceUrl)+'" target="_blank" rel="noopener noreferrer">אתר האולם וגלריית תמונות ↗</a>':'')+(!full&&!v.demo?'<a class="secondary venue-join-link" href="tel:0504088806">להצטרפות ל־BESTEVENT</a><small>כרטיס מלא מופעל לאחר אימות נציג האולם ואישור BESTEVENT.</small>':'')+'</div></article>';}
function venuesView(){const all=directoryVenues(),search=venueSearch.trim().toLocaleLowerCase('he'),list=all.filter(v=>(venueRegion==='all'||v.region===venueRegion)&&(v.name+' '+(v.city||'')+' '+(v.address||'')).toLocaleLowerCase('he').includes(search));return '<div class="toolbar"><div><h2>אולמות וגני אירועים בישראל</h2><p>מאגר ראשוני ממקורות ציבוריים · אינו רשימה מלאה של כל האולמות בישראל.</p></div></div><div class="provider-disclosure">הופעה במאגר אינה מעידה על מנוי או שיתוף פעולה עם BESTEVENT. כרטיס בסיסי מוצג עם לוגו BESTEVENT. כרטיס מלא מיועד לאולמות שותפים לאחר אימות ואישור.</div><div class="venue-directory-controls"><label>חיפוש לפי שם או יישוב<input id="venue-directory-search" type="search" value="'+esc(venueSearch)+'" placeholder="שם אולם, עיר או כתובת"></label>'+providerFilter('venue-region','אזור בארץ',[...new Set(all.map(v=>v.region))],venueRegion)+'<label class="include-demo-venues"><input id="include-demo-venues" type="checkbox" '+(includeDemoVenues?'checked':'')+'> הצגת אולמות הדגמה בנוסף</label></div><p class="muted" role="status">'+list.length+' תוצאות מתוך '+all.length+' רשומות במאגר הנוכחי</p><div class="venue-directory">'+list.map(venueDirectoryCard).join('')+'</div>'+(!list.length?'<p class="design-note">לא נמצאו אולמות לפי החיפוש. נסו שם או אזור אחר.</p>':'');}

document.addEventListener('change',e=>{if(e.target.id==='venue-region'){venueRegion=e.target.value;render();}});
document.addEventListener('click',e=>{const button=e.target.closest('[data-venue-providers]');if(!button)return;const venue=providerVenues.find(v=>v.id===button.dataset.venueProviders);if(!venue)return;providerVenue=venue.id;providerRegion=venue.region;providerCategory='all';providerEvent='all';navigate('providers');});


function venueLayoutCard(v){const large=Object.values(standardSeatingCapacities({venueId:v.id,space:'large'})).reduce((sum,n)=>sum+n,0),small=Object.values(standardSeatingCapacities({venueId:v.id,space:'small'})).reduce((sum,n)=>sum+n,0);return '<section class="venue-capacity-summary"><h4>החללים באולם</h4><div><span>אולם גדול</span><strong>עד '+large+' אורחים</strong></div><div><span>אולם קטן</span><strong>עד '+small+' אורחים</strong></div><p class="muted">אפשרויות סידור: סקיצה סטנדרטית או סידור מיוחד בתיאום עם האולם.</p><small>החללים והקיבולות להדגמה בלבד ואינם מידע מאומת על האולם.</small></section>';}
document.addEventListener('click',e=>{const b=e.target.closest('[data-venue-space]');if(!b)return;venueSpaces[b.dataset.venueSpace]=b.dataset.space;render();});

// Local interaction prototype. These approvals are not server authorization.
const eventSeatingVenues={wedding:{venueId:'sahara',space:'small'}};
const demoVenueMembership={sahara:true,'demo-center':true,'demo-north':false};
const demoLayoutApprovals={};
function seatingState(){const selectedVenue=invitationLocation().venueId;const venueId=demoVenueMembership[selectedVenue]?selectedVenue:customerSeatingReady()?'paid-custom':'';let state=eventSeatingVenues[activeEvent];if(!state||state.venueId!==venueId){if(state?.specialUrl)URL.revokeObjectURL(state.specialUrl);state=eventSeatingVenues[activeEvent]={venueId,space:venueId==='paid-custom'?'custom':state?.space==='small'?'small':'large'};delete demoLayoutApprovals[activeEvent];autoSeatUndo=null;autoSeatMessage='';}return state;}
function seatingGuests(){return activeEvent==='wedding'?guests:(eventGuestLists[activeEvent]||[]);}
function seatingCapacities(){const state=seatingState();if(state.layoutMode==='special'&&state.customCapacities)return state.customCapacities;if(customerSeatingReady()&&!demoVenueMembership[invitationLocation().venueId])return customerSeatingPass().capacities;return standardSeatingCapacities(seatingState());}
function standardSeatingCapacities(state){if(state.venueId==='sahara'&&state.space==='small')return {1:10,2:10,3:12,4:10,5:12,6:10};const count=state.space==='small'?6:12;return Object.fromEntries(Array.from({length:count},(_,i)=>[i+1,state.venueId==='demo-center'?12:10]));}
function seatingVenuePicker(){const state=seatingState();return `<section class="panel seating-venue-picker"><div><h2>האולם והסקיצה שלכם</h2><p class="muted">אולם מנוי להדגמה · ההושבה כלולה במסלול האולם. אין כרגע מערכת מנויים אמיתית מחוברת.</p></div><div class="seating-venue-fields"><label>האולם שנבחר בהזמנה<input id="seating-venue" readonly value="${esc(invitationLocationDetails().name)}" aria-describedby="seating-venue-origin"></label><label>חלל<select id="seating-space" ${!state.venueId?'disabled':''}><option value="large" ${state.space==='large'?'selected':''}>האולם הגדול</option><option value="small" ${state.space==='small'?'selected':''}>האולם הקטן</option></select></label></div><p id="seating-venue-origin" class="muted">האולם מתמלא אוטומטית מעיצוב ההזמנה. כאן בוחרים רק את החלל.</p><button type="button" class="text-button" data-go="invitations">שינוי האולם בעיצוב ההזמנה</button>${state.venueId?`<p class="muted">נטענה סקיצת הדגמה סטנדרטית · ${Object.keys(seatingCapacities()).length} שולחנות. הסקיצה והקיבולת אינן מידע מאומת על האולם.</p>`:''}</section>`;}
function approvalScope(eventId,state){return eventId+':'+state.venueId+':'+state.space;}
function specialLayoutPanel(){const state=seatingState(),approval=demoLayoutApprovals[activeEvent];const ready=approval?.scope===approvalScope(activeEvent,state)&&approval.verified&&!approval.used&&Date.now()<approval.expires;return `<details id="special-layout-panel" class="panel special-layout-panel" open><summary>סקיצה מיוחדת לאירוע · אישור והעלאה</summary><p class="muted">במוצר המלא האולם יאשר העלאה עבור האירוע והחלל שנבחרו באמצעות קוד חד־פעמי. לפני שימוש בסקיצה, האולם יצטרך לאשר גם את התמונה עצמה.</p><div class="approval-demo-note">הדגמה מקומית בלבד: הקוד כאן אינו אישור אמיתי של אולם ואינו מנגנון אבטחה.</div><details id="demo-approval-controls" class="demo-approval-controls"><summary>התנסות בתהליך אישור האולם</summary><p class="muted">הכפתור הבא מדמה אישור מצד האולם. הוא לא שולח הודעה ולא בודק מנוי אמיתי.</p><button type="button" class="secondary" id="demo-issue-layout-code">הדמיית אישור האולם והפקת קוד</button>${approval&&!approval.used&&!approval.verified?`<p class="muted">קוד הדגמה: <bdi>${approval.code}</bdi> · תקף ל־10 דקות, לאירוע ולחלל שנבחרו בלבד.</p>`:''}</details><form id="verify-layout-code" class="layout-code-form"><label for="layout-code">קוד חד־פעמי מהאולם</label><div><input id="layout-code" name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" minlength="6" required autocomplete="one-time-code" placeholder="6 ספרות"><button type="submit" class="secondary">בדיקת קוד</button></div></form><p id="layout-approval-status" class="muted" role="status">${ready?'אישור הדגמה התקבל. ניתן לבחור תמונה אחת להעלאה.':approval?.used?'אישור ההדגמה נוצל. להחלפת סקיצה נדרש אישור חדש.':'העלאה נעולה עד לאישור. אין בקשה שנשלחה לאולם.'}</p><label class="venue-photo-upload">העלאת סקיצה מיוחדת<input id="event-special-layout" type="file" accept="image/jpeg,image/png,image/webp" ${ready?'':'disabled'}></label><small>JPG, PNG או WebP עד 10 מגה. הקובץ נשאר בדפדפן עד לרענון.</small>${state.specialUrl?`<div class="event-special-preview"><h3>הסקיצה המיוחדת שלכם</h3><a href="${esc(state.specialUrl)}" target="_blank" rel="noopener"><img src="${esc(state.specialUrl)}" alt="סקיצה מיוחדת לאירוע ${esc(active().name)}"><span>פתיחה בגודל מלא ↗</span></a><p class="muted">מגדירים את השולחנות לפי הסקיצה הזו לפני השיבוץ. התמונה אינה מזוהה אוטומטית; מיקומי השולחנות ברשת הם סכמטיים.</p><button type="button" class="text-button" id="remove-special-layout">הסרת תמונת הסקיצה המיוחדת</button></div>`:''}</details>`;}
function updateSeatingVenue(venueId,space){if(venueId&&!demoVenueMembership[venueId])return false;if(!['large','small'].includes(space))return false;const previous=seatingState();const candidate={venueId,space};eventSeatingVenues[activeEvent]=candidate;const limits=standardSeatingCapacities(candidate);const invalid=seatingGuests().some(g=>g.table&&(!venueId||!limits[g.table]||occupancy(g.table)>limits[g.table]));if(invalid){eventSeatingVenues[activeEvent]=previous;toast('הסקיצה שנבחרה אינה מתאימה לשיבוצים הקיימים. פנו תחילה את השולחנות הרלוונטיים.');render();return false;}if(previous.specialUrl)URL.revokeObjectURL(previous.specialUrl);delete demoLayoutApprovals[activeEvent];autoSeatUndo=null;autoSeatMessage='';selectedTable=1;if(venueId)invitationLocation().venueId=venueId;render();return true;}
function issueDemoLayoutCode(){const state=seatingState();if(!canAccessSeating()||!demoVenueMembership[state.venueId])return null;const random=new Uint32Array(1);crypto.getRandomValues(random);const code=String(100000+random[0]%900000);demoLayoutApprovals[activeEvent]={scope:approvalScope(activeEvent,state),code,expires:Date.now()+10*60*1000,attempts:0,verified:false,used:false};return code;}
function verifyDemoLayoutCode(code){const state=seatingState(),a=demoLayoutApprovals[activeEvent];if(!canAccessSeating()||!demoVenueMembership[state.venueId]||!a||a.scope!==approvalScope(activeEvent,state))return 'לא נמצא אישור הדגמה לאירוע ולחלל האלה.';if(a.used||a.verified)return 'הקוד כבר נוצל. להעלאה נוספת נדרש אישור חדש.';if(Date.now()>=a.expires)return 'תוקף הקוד פג. נדרש אישור חדש.';if(a.attempts>=5)return 'הגעתם למגבלת הניסיונות. נדרש אישור חדש.';a.attempts++;if(code.trim()!==a.code)return 'הקוד שגוי. נסו שוב.';a.verified=true;return '';}
document.addEventListener('change',e=>{if(e.target.id==='seating-space')updateSeatingVenue(seatingState().venueId,e.target.value);});
document.addEventListener('click',e=>{if(e.target.closest('#demo-issue-layout-code')){issueDemoLayoutCode();render();toast('נוצר קוד להתנסות בלבד. לא נשלחה הודעה לאולם.');}if(e.target.closest('#remove-special-layout')){const state=seatingState();if(state.specialUrl)URL.revokeObjectURL(state.specialUrl);delete state.specialUrl;delete state.customCapacities;state.seatingStarted=false;render();}});
document.addEventListener('submit',e=>{if(e.target.id!=='verify-layout-code')return;e.preventDefault();const error=verifyDemoLayoutCode(new FormData(e.target).get('code'));if(error){$('#layout-approval-status').textContent=error;return;}render();toast('קוד ההדגמה אומת. אפשר להעלות תמונה אחת.');});
document.addEventListener('change',e=>{if(e.target.id!=='event-special-layout')return;const eventId=activeEvent,state=seatingState(),a=demoLayoutApprovals[eventId],file=e.target.files?.[0];if(!file)return;const authorized=()=>canAccessSeating()&&demoVenueMembership[state.venueId]&&eventSeatingVenues[eventId]===state&&demoLayoutApprovals[eventId]===a&&a?.scope===approvalScope(eventId,state)&&a.verified&&!a.used&&Date.now()<a.expires;if(!authorized()){toast('נדרש אישור חדש עבור האולם והחלל שנבחרו');return;}if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){toast('בחרו תמונת JPG, PNG או WebP עד 10 מגה');return;}a.used=true;const url=URL.createObjectURL(file),image=new Image();image.onload=()=>{if(demoLayoutApprovals[eventId]!==a||eventSeatingVenues[eventId]!==state||Date.now()>=a.expires){URL.revokeObjectURL(url);toast('האישור או בחירת האולם השתנו. נדרש אישור חדש.');return;}if(state.specialUrl)URL.revokeObjectURL(state.specialUrl);state.specialUrl=url;state.seatingStarted=false;delete state.customCapacities;if(activeEvent===eventId)render();toast('סקיצת ההדגמה צורפה לאירוע');};image.onerror=()=>{URL.revokeObjectURL(url);if(demoLayoutApprovals[eventId]===a)a.used=false;toast('התמונה אינה תקינה. בחרו תמונה אחרת.');};image.src=url;});

document.addEventListener('change',e=>{if(!e.target.dataset.eventRsvp)return;const g=seatingGuests().find(g=>String(g.id)===e.target.dataset.eventRsvp);if(!g||!rsvpStatuses.includes(e.target.value))return;g.status=e.target.value;if(g.status!=='אישרו')g.table=null;autoSeatUndo=null;autoSeatMessage='';render();});

function invitationLocation(){return invitationLocations[activeEvent]??={venueId:activeEvent==='wedding'?'sahara':'manual',manualName:'',manualAddress:''};}
function invitationLocationDetails(){const location=invitationLocation(),venue=providerVenues.find(v=>v.id===location.venueId&&demoVenueMembership[v.id])||(typeof publicVenueCatalog!=='undefined'?publicVenueCatalog.find(v=>v.id===location.venueId):null);return venue?{name:venue.name,address:venue.address||invitationVenueAddresses[venue.id]||'כתובת מדויקת טרם הוזנה'}:{name:location.manualName,address:location.manualAddress};}
function invitationVenueEditor(){const location=invitationLocation(),details=invitationLocationDetails(),manual=location.venueId==='manual';return '<fieldset class="invitation-venue-editor"><legend>איפה חוגגים?</legend><label for="invitation-venue">בחירת אולם</label><select id="invitation-venue">'+providerVenues.filter(v=>demoVenueMembership[v.id]).map(v=>'<option value="'+v.id+'" '+(location.venueId===v.id?'selected':'')+'>'+esc(v.name)+' · הדגמה</option>').join('')+(typeof publicVenueCatalog==='undefined'?'':publicVenueCatalog.map(v=>'<option value="'+esc(v.id)+'" '+(location.venueId===v.id?'selected':'')+'>'+esc(v.name)+' · אינו שותף</option>').join(''))+'<option value="manual" '+(manual?'selected':'')+'>האולם לא ברשימה — הזנה ידנית</option></select><label for="invitation-location-name">שם האולם / המקום</label><input id="invitation-location-name" maxlength="120" value="'+esc(details.name)+'" '+(manual?'':'readonly')+' placeholder="שם המקום"><label for="invitation-location-address">כתובת האירוע</label><input id="invitation-location-address" maxlength="240" value="'+esc(details.address)+'" '+(manual?'':'readonly')+' placeholder="רחוב, מספר ויישוב"><p class="muted">'+(manual?'מלאו את שם המקום והכתובת. הפרטים מתעדכנים מיד בהזמנה.':'הפרטים מולאו מרשומת האולם. לתיקון כתובת בחרו הזנה ידנית. הושבה רגילה זמינה רק לאולם מנוי; אחרת נדרש מסלול אישי בתשלום.')+'</p></fieldset>';}
document.addEventListener('change',e=>{if(e.target.id!=='invitation-venue')return;const id=e.target.value;if(id!=='manual'&&!providerVenues.some(v=>v.id===id&&demoVenueMembership[v.id])&&!(typeof publicVenueCatalog!=='undefined'&&publicVenueCatalog.some(v=>v.id===id)))return;if(demoVenueMembership[id]&&!updateSeatingVenue(id,seatingState().space))return;invitationLocation().venueId=id;if(!demoVenueMembership[id]){delete demoLayoutApprovals[activeEvent];autoSeatUndo=null;autoSeatMessage='';}render();});
document.addEventListener('input',e=>{if(!['invitation-location-name','invitation-location-address'].includes(e.target.id))return;const location=invitationLocation();if(location.venueId!=='manual')return;location[e.target.id==='invitation-location-name'?'manualName':'manualAddress']=e.target.value;const details=invitationLocationDetails();$('#invitation-venue-name-preview').textContent=details.name;$('#invitation-venue-address-preview').textContent=details.address;const waze=$('#invitation-waze-preview');if(waze)waze.innerHTML=invitationWazeMarkup();});
function canAccessSeating(){const venueId=invitationLocation().venueId;return Boolean((venueId!=='manual'&&demoVenueMembership[venueId])||customerSeatingReady());}
// Customer-paid access is a local checkout simulation, never proof of payment.
const customerSeatingPasses={};
function customerSeatingScope(){const location=invitationLocation(),details=invitationLocationDetails();return JSON.stringify([activeEvent,location.venueId,details.name,details.address]);}
function customerSeatingPass(){const pass=customerSeatingPasses[activeEvent];return pass?.scope===customerSeatingScope()?pass:null;}
function customerSeatingReady(){const pass=customerSeatingPass();return Boolean(pass?.demoPaid&&(pass.imageUrl||pass.manualPlan)&&pass.ready&&pass.capacities&&!pass.editingLayout);}
function paidSeatingOffer(){if(demoVenueMembership[invitationLocation().venueId])return '';return '<div class="customer-seating-offer"><div><h3>האולם אינו שותף — ההושבה הרגילה נעולה</h3><p>תשלום חד־פעמי לאירוע, יצירת פריסה ידנית או העלאת סקיצה, ואישור השולחנות לפני תחילת השיבוץ.</p></div><button type="button" class="secondary" data-go="seatingPurchase">'+(customerSeatingReady()?'ניהול הסקיצה והמסלול האישי':'למסלול הושבה פרטי בתשלום')+'</button></div>';}
function paidSeatingView(){const pass=customerSeatingPass(),details=invitationLocationDetails();return '<section class="panel customer-seating-setup"><h2>סידורי הושבה במסלול אישי</h2><p class="muted">עבור '+esc(active().name)+' · '+esc(details.name||'יש להזין את שם האולם בהזמנה')+'</p><div class="approval-demo-note">הדגמת תהליך בלבד. אין כאן סליקה או חיוב, ומחיר המסלול עדיין לא נקבע. ההרשאה והסקיצה נשמרות עד לרענון.</div><ol class="customer-seating-steps"><li><h3>תשלום חד־פעמי לאירוע</h3><p class="muted">במוצר המלא התשלום יאומת בשרת. התנסות זו אינה מבקשת פרטי כרטיס.</p><button type="button" class="secondary" id="demo-customer-payment" '+(pass?.demoPaid?'disabled':'')+'>'+(pass?.demoPaid?'הדמיית התשלום הושלמה':'הדמיית תשלום — ללא חיוב')+'</button></li><li><h3>בחירת בסיס לסקיצה</h3><label class="venue-photo-upload">תמונת הסקיצה<input type="file" id="customer-seating-image" accept="image/jpeg,image/png,image/webp" '+(pass?.demoPaid?'':'disabled')+'></label><small>אפשר להעלות תמונה כרקע או לבנות פריסה ללא תמונה. JPG, PNG או WebP עד 10 מגה.</small>'+(pass?.imageUrl?'<img class="customer-plan-preview" src="'+esc(pass.imageUrl)+'" alt="הסקיצה שהועלתה לאירוע"><small>סקיצה הועלתה · ניתן להחליף תמונה</small>':'')+'<button type="button" class="secondary" id="customer-manual-plan" '+(pass?.demoPaid?'':'disabled')+'>יצירת סקיצה ללא תמונה</button></li><li><h3>הגדרת השולחנות לפי הסקיצה</h3><p class="muted">הגדירו כמות שולחנות ומקומות ראשונית. לאחר מכן תוכלו לגרור שולחנות, לשנות את מספר המקומות בכל שולחן ולשמור את הפריסה.</p><form id="customer-seating-plan"><div class="form-grid"><label>מספר שולחנות<input type="number" name="tables" min="1" max="60" step="1" value="'+(pass?.capacities?Object.keys(pass.capacities).length:12)+'" required '+(pass?.imageUrl||pass?.manualPlan?'':'disabled')+'></label><label>מקומות בכל שולחן<input type="number" name="seats" min="1" max="24" step="1" value="10" required '+(pass?.imageUrl||pass?.manualPlan?'':'disabled')+'></label></div><button class="secondary" type="submit" '+(pass?.imageUrl||pass?.manualPlan?'':'disabled')+'>הכנת רשימת שולחנות</button></form>'+(pass?.capacities?(pass.ready&&!pass.editingLayout?customerPlanMap(false)+'<button type="button" class="secondary" id="edit-customer-layout">עריכת הפריסה</button><button type="button" class="primary" data-go="seating">להמשך שיבוץ מוזמנים ←</button>':'<form id="activate-customer-seating">'+customerPlanMap(true)+'<div class="customer-table-capacities">'+Object.entries(pass.capacities).map(([table,capacity])=>'<label>שולחן '+table+'<input name="table-'+table+'" type="number" value="'+capacity+'" min="1" max="24" step="1" required></label>').join('')+'</div><p class="muted">גררו את השולחנות למיקום הרצוי. אפשר גם להזיז שולחן באמצעות מקשי החצים. שמירת הפריסה שומרת גם את הקיבולת של כל שולחן.</p><button type="submit" class="primary">שמירת הפריסה והמשך להושבה ←</button></form>'):'')+'</li></ol><button type="button" class="text-button" data-go="invitations">עריכת שם האולם וכתובתו</button></section>';}
function customerSeatingReference(){return '<section class="panel customer-seating-reference"><div class="panel-title"><h2>הפריסה שלכם · מסלול אישי</h2><button type="button" class="secondary" id="edit-customer-layout">עריכת הפריסה</button></div><p class="muted">לחצו על שולחן במפה כדי לשבץ מוזמנים. תשלום במסלול זה הוא הדגמה בלבד.</p></section>';}
function customerPlanFits(capacities){const people=seatingGuests();return people.every(g=>!g.table||(capacities[g.table]&&people.filter(other=>other.table===g.table).reduce((sum,other)=>sum+other.count,0)<=capacities[g.table]));}
document.addEventListener('click',e=>{if(!e.target.closest('#demo-customer-payment'))return;if(demoVenueMembership[invitationLocation().venueId]){toast('האולם שנבחר כבר מופיע כמנוי הדגמה');return;}if(!invitationLocationDetails().name.trim()){toast('הזינו קודם את שם האולם בעיצוב ההזמנה');return;}const old=customerSeatingPasses[activeEvent];if(old?.imageUrl)URL.revokeObjectURL(old.imageUrl);customerSeatingPasses[activeEvent]={scope:customerSeatingScope(),demoPaid:true,ready:false};render();toast('התנסות בלבד: לא בוצע חיוב. בחרו תמונת רקע או יצירת סקיצה ללא תמונה.');});
document.addEventListener('change',e=>{if(e.target.id!=='customer-seating-image')return;const uploadAccountGeneration=accountGeneration;const pass=customerSeatingPass(),eventId=activeEvent,file=e.target.files?.[0];if(!pass?.demoPaid||!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){toast('בחרו JPG, PNG או WebP עד 10 מגה');return;}const version=(pass.uploadVersion||0)+1;pass.uploadVersion=version;const url=URL.createObjectURL(file),image=new Image();image.onload=()=>{if(uploadAccountGeneration!==accountGeneration||customerSeatingPasses[eventId]!==pass||pass.uploadVersion!==version){URL.revokeObjectURL(url);return;}if(pass.imageUrl)URL.revokeObjectURL(pass.imageUrl);pass.imageUrl=url;pass.ready=false;if(activeEvent===eventId)render();toast('הסקיצה צורפה. הגדירו שולחנות ואשרו לפני השיבוץ.');};image.onerror=()=>{URL.revokeObjectURL(url);toast('לא ניתן לפתוח את הסקיצה. בחרו תמונה תקינה.');};image.src=url;});
document.addEventListener('submit',e=>{if(!['customer-seating-plan','activate-customer-seating'].includes(e.target.id))return;e.preventDefault();const pass=customerSeatingPass();if(!pass?.demoPaid||(!pass.imageUrl&&!pass.manualPlan)){toast('נדרשים תשלום הדגמה ובחירת בסיס לסקיצה לפני ההמשך');return;}const form=new FormData(e.target);if(e.target.id==='customer-seating-plan'){const tables=Number(form.get('tables')),seats=Number(form.get('seats'));if(!Number.isInteger(tables)||tables<1||tables>60||!Number.isInteger(seats)||seats<1||seats>24)return;const capacities=Object.fromEntries(Array.from({length:tables},(_,i)=>[i+1,seats]));if(!customerPlanFits(capacities)){toast('ההגדרה החדשה אינה מתאימה לשיבוצים הקיימים. השיבוצים לא שונו.');return;}pass.capacities=capacities;pass.layoutDraft=customerDefaultPositions(capacities,pass.positions);pass.editingLayout=true;pass.ready=false;render();return;}if(!pass.capacities)return;const capacities={};for(const table of Object.keys(pass.capacities)){const capacity=Number(form.get('table-'+table));if(!Number.isInteger(capacity)||capacity<1||capacity>24)return;capacities[table]=capacity;}if(!customerPlanFits(capacities)){toast('אין מספיק מקומות לשיבוצים הקיימים. השיבוצים לא שונו.');return;}pass.capacities=capacities;pass.positions=customerDefaultPositions(capacities,pass.layoutDraft||pass.positions);delete pass.layoutDraft;pass.editingLayout=false;pass.ready=true;eventSeatingVenues[activeEvent]={venueId:'paid-custom',space:'custom'};autoSeatUndo=null;autoSeatMessage='';selectedTable=1;navigate('seating');});

function canAssignSeating(){if(!canAccessSeating())return false;if(customerSeatingReady()&&!demoVenueMembership[invitationLocation().venueId])return true;const state=seatingState();return Boolean(state.seatingStarted&&(state.layoutMode==='standard'||(state.layoutMode==='special'&&state.specialUrl&&state.customCapacities)));}
function layoutModePicker(){const mode=seatingState().layoutMode;return '<section class="layout-mode-picker"><h3>באיזו סקיצה משתמשים?</h3><div role="group" aria-label="בחירת סוג סקיצה"><button type="button" data-layout-mode="standard" aria-pressed="'+(mode==='standard')+'"><strong>סקיצה סטנדרטית</strong><span>סידור השולחנות הקבוע של החלל</span></button><button type="button" data-layout-mode="special" aria-pressed="'+(mode==='special')+'"><strong>סקיצה מיוחדת</strong><span>העלאת הסידור המבוקש והגדרת שולחנות</span></button></div></section>';}
function standardLayoutPreview(){const tables=Object.keys(standardSeatingCapacities(seatingState()));return '<section class="panel standard-layout-preview"><h3>הסקיצה הסטנדרטית · תצוגה מקדימה</h3><div class="venue-mini-plan"><div class="mini-plan-stage">במה וחופה</div><div class="mini-plan-tables">'+tables.map(table=>'<span>'+table+'</span>').join('')+'</div><div class="mini-plan-dance">רחבת ריקודים</div></div><p class="muted">סקיצת הדגמה · '+tables.length+' שולחנות. אחרי אישור הבחירה תיפתח רשימת המוזמנים לשיבוץ.</p><button type="button" class="primary" id="start-standard-seating">בחירת הסקיצה והתחלת שיבוץ ←</button></section>';}
function specialLayoutSetup(){const limits=seatingState().customCapacities;return '<form id="start-special-seating" class="panel special-layout-setup"><h3>הגדירו שולחנות לפי הסקיצה שהעליתם</h3><p class="muted">מספרו את השולחנות בסקיצה ברצף החל מ־1. הרשימה תיבנה לפי המספר והקיבולת שתזינו, ללא זיהוי אוטומטי מהתמונה.</p><div class="form-grid"><label>מספר שולחנות<input name="tables" type="number" min="1" max="60" step="1" value="'+(limits?Object.keys(limits).length:12)+'" required></label><label>מקומות בכל שולחן<input name="seats" type="number" min="1" max="24" step="1" value="'+(limits?Object.values(limits)[0]:10)+'" required></label></div><button type="submit" class="primary">אישור הסקיצה והתחלת שיבוץ ←</button></form>';}
document.addEventListener('click',e=>{const button=e.target.closest('[data-layout-mode]');if(button){if(!canAccessSeating()||!demoVenueMembership[invitationLocation().venueId])return;const state=seatingState();if(!['standard','special'].includes(button.dataset.layoutMode))return;if(state.layoutMode!==button.dataset.layoutMode){state.layoutMode=button.dataset.layoutMode;state.seatingStarted=false;autoSeatUndo=null;autoSeatMessage='';}render();}if(e.target.closest('#start-standard-seating')){if(!canAccessSeating())return;const state=seatingState();if(state.layoutMode!=='standard')return;if(!customerPlanFits(standardSeatingCapacities(state))){toast('הסקיצה הסטנדרטית אינה מתאימה לשיבוצים הקיימים. השיבוצים נשמרו.');return;}state.seatingStarted=true;selectedTable=1;render();}});
document.addEventListener('submit',e=>{if(e.target.id!=='start-special-seating')return;e.preventDefault();if(!canAccessSeating())return;const state=seatingState();if(state.layoutMode!=='special'||!state.specialUrl)return;const form=new FormData(e.target),tables=Number(form.get('tables')),seats=Number(form.get('seats'));if(!Number.isInteger(tables)||tables<1||tables>60||!Number.isInteger(seats)||seats<1||seats>24)return;const capacities=Object.fromEntries(Array.from({length:tables},(_,i)=>[i+1,seats]));if(!customerPlanFits(capacities)){toast('ההגדרה אינה מתאימה לשיבוצים הקיימים. בחרו מספר שולחנות וקיבולת מתאימים.');return;}state.customCapacities=capacities;state.seatingStarted=true;selectedTable=1;autoSeatUndo=null;autoSeatMessage='';render();});
// Local profile and user-initiated sharing. No authentication or message delivery service.
let localEmailProfile=null,sharingSnapshot=null;
const sharingDialog=document.createElement('dialog');sharingDialog.id='sharing-dialog';sharingDialog.setAttribute('aria-label','שיתוף והדפסת רשימה');document.body.appendChild(sharingDialog);
const profileDialog=document.createElement('dialog');profileDialog.id='email-profile-dialog';profileDialog.setAttribute('aria-label','חשבון משתמש');document.body.appendChild(profileDialog);
function localProfileLabel(){return accountUser?'החשבון שלי':'התחברות / הרשמה';}
function openEmailProfile(){openAccountDialog();}
function sharingToolbar(){const labels={guests:'רשימת מוזמנים',seating:'רשימת הושבה',gifts:'יומן מתנות',eventGifts:'מתנות האירוע'};if(!labels[current]||(current==='seating'&&!canAssignSeating()))return '';return '<div class="list-sharing-toolbar"><span>'+labels[current]+'</span><button class="secondary" type="button" id="open-list-sharing">'+(current==='eventGifts'?'שליחת רשימת המתנות של האירוע':'שיתוף ושליחה')+'</button><button class="secondary" type="button" id="print-current-list">הדפסת הרשימה</button></div>';}
function buildListReport(view=current){const event=myEvents.find(e=>e.id===activeEvent);if(['guests','seating','eventGifts'].includes(view)&&!event)throw Error('לא נמצא אירוע לרשימה');if(view==='seating'&&!canAssignSeating())throw Error('יש לבחור ולאשר סקיצה לפני שיתוף ההושבה');let title,headers,rows;if(view==='guests'){title='רשימת מוזמנים · '+event.name;headers=['שם המוזמן','מספר אורחים','אישור הגעה','קבוצה / צד','שולחן'];rows=seatingGuests().map(g=>[g.name,g.count,g.status,g.side||g.group||'ללא ציון צד',g.table||'טרם שובצו']);}else if(view==='seating'){title='רשימת הושבה · '+event.name;headers=['שולחן','שם המוזמן','מספר אורחים','אישור הגעה'];rows=[...seatingGuests()].sort((a,b)=>(a.table||Infinity)-(b.table||Infinity)||a.name.localeCompare(b.name,'he')).map(g=>[g.table||'ללא שיבוץ',g.name,g.count,g.status]);}else if(view==='gifts'||view==='eventGifts'){title=view==='gifts'?'יומן המתנות · כל האירועים':'מתנות · '+event.name;headers=['איש קשר','כיוון','אירוע','סכום / תיאור המתנה','תאריך'];const list=view==='gifts'?gifts:gifts.filter(g=>g.eventId===activeEvent||(!g.eventId&&g.event===event.name&&g.date===event.date&&g.direction==='received'));rows=list.map(g=>[giftContact(g.person).name,g.direction==='received'?'קיבלנו':'נתנו',g.event,giftValueText(g),date(g.date)]);}else throw Error('אין רשימה לשיתוף במסך הזה');rows.sort((a,b)=>String(a[view==='seating'?1:0]).localeCompare(String(b[view==='seating'?1:0]),'he',{numeric:true,sensitivity:'base'}));return {title,headers,rows,note:'כל הרשומות ברשימה, כולל רשומות שאינן מוצגות במסנן הנוכחי. נתוני הדגמה; שינויים נשמרים עד רענון בלבד.'};}
function reportText(report){return ['BESTEVENT',report.title,report.note,'',...report.rows.map((row,index)=>(index+1)+'. '+row.map((value,i)=>report.headers[i]+': '+String(value)).join(' | ')),...(!report.rows.length?['אין רשומות ברשימה.']:[])].join('\n');}
function reportPrintHtml(report){return '<!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><title>'+esc(report.title)+'</title><style>@page{size:A4;margin:14mm}body{font:13px Arial,sans-serif;color:#442719}h1{font-size:22px}p{font-size:11px;color:#765744}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{border:1px solid #d4bdaa;padding:8px;text-align:right;overflow-wrap:anywhere;white-space:pre-wrap}th{background:#eee3da}thead{display:table-header-group}tr{break-inside:avoid}</style></head><body><p>BESTEVENT</p><h1>'+esc(report.title)+'</h1><p>'+esc(report.note)+'</p><table><thead><tr>'+report.headers.map(h=>'<th scope="col">'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+report.rows.map(row=>'<tr>'+row.map(value=>'<td>'+esc(value)+'</td>').join('')+'</tr>').join('')+'</tbody></table>'+(!report.rows.length?'<p>אין רשומות ברשימה.</p>':'')+'</body></html>';}
function openListSharing(){try{sharingSnapshot=buildListReport();}catch(error){toast(error.message);return;}sharingDialog.innerHTML='<div class="dialog-top"><h2>שיתוף ושליחה</h2><button class="close" type="button" aria-label="סגירה">×</button></div><h3>'+esc(sharingSnapshot.title)+'</h3><p class="muted">'+sharingSnapshot.rows.length+' רשומות · כל הרשומות, ללא סינון. בדקו את התוכן והנמען לפני השליחה.</p><label class="sharing-preview-label" for="sharing-preview">תצוגה מקדימה<textarea id="sharing-preview" rows="8" readonly></textarea></label><label class="sharing-preview-label" for="sharing-email">למי לשלוח במייל? (לא חובה)<input id="sharing-email" type="email" maxlength="254" dir="ltr" placeholder="name@example.com" value="'+esc(localEmailProfile?.email||'')+'"></label><div class="sharing-actions"><button type="button" class="primary" id="share-whatsapp">שיתוף PDF ב־WhatsApp</button><button type="button" class="secondary" id="share-email">שליחה במייל</button><button type="button" class="secondary" id="share-print">הדפסה / שמירה כ־PDF</button><button type="button" class="secondary" id="download-list">הורדת הרשימה כ־PDF</button></div><p class="muted" id="sharing-status" role="status">הפעולה תפתח הודעה מוכנה. בחירת איש הקשר ואישור השליחה נעשים על ידכם ב־WhatsApp או באפליקציית הדואר. לא נשלח דבר אוטומטית.</p>';$('#sharing-preview').value=reportText(sharingSnapshot);sharingDialog.showModal();prepareSharingPdf(sharingSnapshot);}
let sharingPdfFile=null,sharingPdfSnapshot=null;
function savePdfFile(file){const url=URL.createObjectURL(file),link=document.createElement('a');link.href=url;link.download=file.name;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function prepareSharingPdf(report){sharingPdfFile=null;sharingPdfSnapshot=report;$('#share-whatsapp').disabled=true;$('#download-list').disabled=true;$('#sharing-status').textContent='מכינים PDF בעברית, לפי סדר א׳–ב׳…';try{const blob=await buildBesteventPdf(report);if(sharingPdfSnapshot!==report)return;sharingPdfFile=new File([blob],'BESTEVENT-'+(report.title.replace(/[^\p{L}\p{N} -]/gu,'').trim()||'list')+'.pdf',{type:'application/pdf'});$('#sharing-status').textContent='ה־PDF מוכן. בטלפון בחרו WhatsApp בחלון השיתוף. אם שיתוף קבצים אינו נתמך, הקובץ יורד לצירוף ידני. לא נשלח דבר אוטומטית.';}catch(error){$('#sharing-status').textContent='יצירת PDF לא הושלמה. אפשר להשתמש בהדפסה / שמירה כ־PDF.';}finally{if(sharingPdfSnapshot===report){$('#share-whatsapp').disabled=!sharingPdfFile;$('#download-list').disabled=!sharingPdfFile;}}}
function downloadList(report){if(sharingPdfFile&&sharingPdfSnapshot===report)savePdfFile(sharingPdfFile);else toast('המתינו לסיום הכנת ה־PDF');}
function printList(report){const frame=document.createElement('iframe');frame.className='report-print-frame';frame.title='תצוגת הדפסת הרשימה';frame.onload=()=>{const cleanup=()=>frame.remove();frame.contentWindow.addEventListener('afterprint',cleanup,{once:true});frame.contentWindow.focus();frame.contentWindow.print();setTimeout(cleanup,120000);};frame.srcdoc=reportPrintHtml(report);document.body.appendChild(frame);}
function listShareLink(channel,report,email=''){const text=reportText(report),encoded=encodeURIComponent(text);if(channel==='whatsapp')return encoded.length>6000?null:'https://wa.me/?text='+encoded;if(channel==='email'){if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw Error('הזינו כתובת מייל תקינה');const url='mailto:'+encodeURIComponent(email)+'?subject='+encodeURIComponent(report.title)+'&body='+encoded;return url.length>1800?null:url;}throw Error('ערוץ שיתוף לא מוכר');}
async function sendPreparedList(channel){if(!sharingSnapshot)return;if(channel==='whatsapp'){if(!sharingPdfFile||sharingPdfSnapshot!==sharingSnapshot){$('#sharing-status').textContent='המתינו לסיום הכנת ה־PDF';return;}const file=sharingPdfFile;try{if(typeof navigator.share==='function'&&typeof navigator.canShare==='function'&&navigator.canShare({files:[file]})){await navigator.share({files:[file],title:sharingSnapshot.title});$('#sharing-status').textContent='חלון השיתוף נסגר. השליחה נעשית רק באישורכם באפליקציה שבחרתם.';}else{savePdfFile(file);$('#sharing-status').textContent='ה־PDF הורד. פתחו WhatsApp, בחרו צירוף מסמך ובחרו בקובץ שהורד.';}}catch(error){if(error.name==='AbortError'){$('#sharing-status').textContent='השיתוף בוטל. ה־PDF עדיין זמין להורדה.';}else{savePdfFile(file);$('#sharing-status').textContent='שיתוף ישיר לא הצליח. ה־PDF הורד לצירוף ידני ב־WhatsApp.';}}return;}const email=$('#sharing-email').value.trim();let url;try{url=listShareLink(channel,sharingSnapshot,email);}catch(error){$('#sharing-status').textContent=error.message;return;}if(!url){downloadList(sharingSnapshot);$('#sharing-status').textContent='הרשימה ארוכה מדי להודעה בקישור, ולכן הורדה כקובץ. צרפו את הקובץ ידנית להודעה. לא נשלח דבר.';return;}if(channel==='whatsapp')window.open(url,'_blank','noopener,noreferrer');else window.location.href=url;$('#sharing-status').textContent='נפתחה בקשה להכנת הודעה. אם לא נפתח יישום, הורידו את הרשימה כקובץ וצרפו אותו ידנית. השליחה עדיין דורשת אישור שלכם.';}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='open-email-profile')openEmailProfile();if(b.id==='clear-email-profile'){localEmailProfile=null;profileDialog.close();$('#open-email-profile').textContent=localProfileLabel();toast('הפרופיל המקומי נוקה');}if(b.id==='open-list-sharing')openListSharing();if(b.id==='print-current-list'){try{printList(buildListReport());}catch(error){toast(error.message);}}if(b.id==='share-whatsapp')sendPreparedList('whatsapp');if(b.id==='share-email')sendPreparedList('email');if(b.id==='share-print'&&sharingSnapshot)printList(sharingSnapshot);if(b.id==='download-list'&&sharingSnapshot)downloadList(sharingSnapshot);});
document.addEventListener('submit',e=>{if(e.target.id!=='local-email-profile')return;e.preventDefault();const form=new FormData(e.target),name=String(form.get('name')||'').trim(),email=String(form.get('email')||'').trim();if(!name||name.length>80||email.length>254||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){toast('מלאו שם וכתובת מייל תקינה');return;}localEmailProfile={name,email};profileDialog.close();$('#open-email-profile').textContent=localProfileLabel();toast('הפרופיל נשמר מקומית עד לרענון; המייל לא אומת');});
document.addEventListener('click',e=>{const b=e.target.closest('[data-gift-entry-mode]');if(!b)return;const manual=b.dataset.giftEntryMode==='manual';if(manual===giftManualEntry)return;giftManualEntry=manual;$('#gift-person').value='';if(!manual)$('#gift-contact-search').value='';renderGiftContacts();$('#gift-contact-search').focus();});
function validSupplierPhone(phone){const digits=phone.replace(/\D/g,'');return phone.length<=25&&/^\+?[0-9 ()-]+$/.test(phone)&&digits.length>=7&&digits.length<=15;}
function supplierPhoneMarkup(phone){return phone&&validSupplierPhone(phone)?'<a class="supplier-phone" href="tel:'+phone.replace(/[^+0-9]/g,'')+'"><bdi>'+esc(phone)+'</bdi></a>':'<span class="muted">לא הוזן</span>';}

function invitationUploadEditor(){const upload=uploadedInvitations[activeEvent];return '<section class="invitation-upload-editor panel"><h3>תמונת רקע להזמנה</h3><label class="venue-photo-upload">'+(upload?'החלפת תמונת הרקע':'העלאת תמונת רקע')+'<input type="file" id="upload-custom-invitation" accept="image/jpeg,image/png,image/webp"></label><small>JPG, PNG או WebP עד 10 מגה. התמונה תשמש כרקע; פרטי ההזמנה והכפתורים נשארים זמינים.</small>'+(upload?'<p>'+esc(upload.name)+'</p><button type="button" class="text-button" id="remove-custom-invitation">הסרת תמונת הרקע</button>':'')+'</section>';}
function uploadedInvitationPreview(){const upload=uploadedInvitations[activeEvent];return upload?'<img class="invitation-background-image" src="'+esc(upload.url)+'" alt="" aria-hidden="true"><span class="invitation-background-veil" aria-hidden="true"></span>':'';}
document.addEventListener('click',e=>{const b=e.target.closest('[data-invitation-design]');if(b&&['builtin','custom'].includes(b.dataset.invitationDesign)){invitationDesignModes[activeEvent]=b.dataset.invitationDesign;render();}if(e.target.closest('#remove-custom-invitation')){if(uploadedInvitations[activeEvent])URL.revokeObjectURL(uploadedInvitations[activeEvent].url);delete uploadedInvitations[activeEvent];invitationUploadVersions[activeEvent]=(invitationUploadVersions[activeEvent]||0)+1;invitationDesignModes[activeEvent]='builtin';render();}});
document.addEventListener('change',e=>{if(e.target.id!=='upload-custom-invitation')return;const uploadAccountGeneration=accountGeneration;const file=e.target.files?.[0],eventId=activeEvent;if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){toast('בחרו תמונת הזמנה מסוג JPG, PNG או WebP עד 10 מגה');return;}const version=(invitationUploadVersions[eventId]||0)+1;invitationUploadVersions[eventId]=version;const url=URL.createObjectURL(file),image=new Image();image.onload=()=>{if(uploadAccountGeneration!==accountGeneration||invitationUploadVersions[eventId]!==version){URL.revokeObjectURL(url);return;}if(uploadedInvitations[eventId])URL.revokeObjectURL(uploadedInvitations[eventId].url);uploadedInvitations[eventId]={url,name:file.name};invitationDesignModes[eventId]='custom';if(activeEvent===eventId)render();toast('תמונת הרקע נוספה להזמנה');};image.onerror=()=>{URL.revokeObjectURL(url);toast('לא ניתן לפתוח את התמונה. נסו קובץ תמונה אחר.');};image.src=url;});
const accountArrays={guests,gifts,myEvents,expenseRecords,additionalGiftContacts};
const accountMaps={eventGuestLists,invitationLocations,invitationHeadings,invitationMessages,invitationDesignModes,uploadedInvitations,venuePhotos,venueLayouts,venueSpaces,eventSeatingVenues,customerSeatingPasses,localRatings};
let accountUser=null,accountRevision=0,accountRestoring=false,accountSaveTimer=null,accountSaving=false,accountResave=false,accountConflict=false,lastAccountSnapshot='',accountGeneration=0,accountMode='login';
function accountStatus(message){const element=$('#account-save-status');if(!element)return;const hide=message==='התחברו כדי לשמור את הנתונים בחשבון';element.hidden=hide;element.textContent=hide?'':message;}
function accountSnapshot(){const data={};for(const [key,value] of Object.entries(accountArrays))data[key]=value;for(const [key,value] of Object.entries(accountMaps))data[key]=value;return {version:1,data,activeEvent,invitationColor,expenseId,nextGiftContactId};}
function emptyAccountSnapshot(){return {version:1,data:Object.fromEntries([...Object.keys(accountArrays).map(key=>[key,[]]),...Object.keys(accountMaps).map(key=>[key,{}])]),activeEvent:'wedding',invitationColor:0,expenseId:1,nextGiftContactId:-1};}
function restoreAccountSnapshot(snapshot){if(snapshot?.version!==1||!snapshot.data)throw Error('גרסת המידע בחשבון אינה נתמכת');accountRestoring=true;try{for(const [key,target] of Object.entries(accountArrays)){const value=snapshot.data[key];if(!Array.isArray(value))throw Error('מידע החשבון אינו תקין');}for(const key of Object.keys(accountMaps)){const value=snapshot.data[key];if(!value||typeof value!=='object'||Array.isArray(value))throw Error('מידע החשבון אינו תקין');}for(const [key,target] of Object.entries(accountArrays))target.splice(0,target.length,...snapshot.data[key]);for(const [key,target] of Object.entries(accountMaps)){for(const name of Object.keys(target))delete target[name];for(const [name,value] of Object.entries(snapshot.data[key]))if(!['__proto__','constructor','prototype'].includes(name))target[name]=value;}activeEvent=snapshot.activeEvent||myEvents[0]?.id||'wedding';invitationColor=Number(snapshot.invitationColor)||0;expenseId=Number(snapshot.expenseId)||1;nextGiftContactId=Number(snapshot.nextGiftContactId)||-1;for(const key of Object.keys(demoLayoutApprovals))delete demoLayoutApprovals[key];autoSeatUndo=null;autoSeatMessage='';navigationTrail.length=0;renderedEvent=null;giftEventContext=null;giftContacts=[];sharingSnapshot=null;for(const dialog of [sharingDialog,profileDialog,tableDialog,financeDialog,guestEntryDialog,$('#gift-dialog'),$('#person-dialog')]){if(dialog?.open)dialog.close();}current='home';query='';giftFilter='all';localEmailProfile=accountUser?{name:accountUser.username,email:accountUser.email}:null;navigate('home');}finally{accountRestoring=false;}}
async function portableAccountSnapshot(snapshot){async function walk(value){if(typeof value==='string'&&value.startsWith('blob:')){const response=await fetch(value);if(!response.ok)throw Error('לא ניתן לשמור אחת התמונות');const blob=await response.blob();return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('לא ניתן לקרוא תמונה לשמירה'));reader.readAsDataURL(blob);});}if(Array.isArray(value))return await Promise.all(value.map(walk));if(value&&typeof value==='object'){const entries=await Promise.all(Object.entries(value).map(async([key,item])=>[key,await walk(item)]));return Object.fromEntries(entries);}return value;}return await walk(JSON.parse(JSON.stringify(snapshot)));}
async function accountApi(url,{method='GET',data}={}){const response=await fetch(url,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-BESTEVENT-Client':'1'},...(data?{body:JSON.stringify(data)}:{})});let body;try{body=await response.json();}catch{throw Error('שירות החשבונות לא זמין בכתובת הזו. פתחו את הגרסה המקומית עם שרת החשבונות.');}if(!response.ok){const error=Error(body.error||'לא ניתן להשלים את הפעולה');error.status=response.status;throw error;}return body;}
function queueAccountSave(){if(!accountUser||accountRestoring||accountConflict)return;clearTimeout(accountSaveTimer);accountStatus('שינויים ממתינים לשמירה…');accountSaveTimer=setTimeout(()=>saveAccountNow(),700);}
async function saveAccountNow(){clearTimeout(accountSaveTimer);if(!accountUser||accountRestoring||accountConflict)return false;if(accountSaving){accountResave=true;return false;}const generation=accountGeneration,raw=JSON.stringify(accountSnapshot());if(raw===lastAccountSnapshot){accountStatus('כל השינויים נשמרו בחשבון');return true;}accountSaving=true;accountStatus('שומר בחשבון…');let saved=false;try{const state=await portableAccountSnapshot(JSON.parse(raw));if(generation!==accountGeneration)return false;const result=await accountApi('/api/state',{method:'PUT',data:{revision:accountRevision,state}});if(generation!==accountGeneration)return false;accountRevision=result.revision;lastAccountSnapshot=raw;accountStatus('כל השינויים נשמרו בחשבון');saved=true;}catch(error){if(generation===accountGeneration){if(error.status===409)accountConflict=true;accountStatus('לא נשמר: '+error.message);}}finally{accountSaving=false;if(accountResave&&generation===accountGeneration&&!accountConflict){accountResave=false;queueAccountSave();}}return saved;}
async function loadAccountData(user){accountRestoring=true;$('#content').inert=true;try{const result=await accountApi('/api/state');accountGeneration++;accountUser=user;accountRevision=result.revision;accountConflict=false;const snapshot=result.state||emptyAccountSnapshot();restoreAccountSnapshot(snapshot);lastAccountSnapshot=result.state?JSON.stringify(accountSnapshot()):'';$('#open-email-profile').textContent='החשבון שלי';accountStatus(result.state?'הנתונים נטענו מהחשבון':'חשבון חדש · התחילו בהקמת אירוע');}finally{accountRestoring=false;$('#content').inert=false;}}
function accountDialogContents(){if(accountUser)return '<div class="dialog-top"><h2>החשבון שלי</h2><button type="button" class="close" aria-label="סגירה">×</button></div><p>מחוברים בשם <strong>'+esc(accountUser.username)+'</strong></p><p class="muted">הנתונים נשמרים במסד הנתונים של השרת המקומי. גישה מהאינטרנט ומחשב אחר תחייב פרסום שרת בהמשך; GitHub Pages אינו שרת חשבונות.</p><p class="muted">'+(accountUser.email?'מייל החשבון: '+esc(accountUser.email)+' · הכתובת טרם אומתה':'לא הוגדר מייל בחשבון.')+'</p><div class="sharing-actions"><button type="button" class="primary" id="account-save-now">שמירה עכשיו</button><button type="button" class="secondary" id="account-reload">טעינת העותק השמור בחשבון</button><button type="button" class="secondary" id="account-logout">שמירה ויציאה מהחשבון</button></div><p class="muted" id="account-form-status" role="status"></p>'+deviceAuthEnrollmentMarkup();return '<div class="dialog-top"><h2>'+ (accountMode==='register'?'פתיחת חשבון':'התחברות לחשבון')+'</h2><button type="button" class="close" aria-label="סגירה">×</button></div><div class="gift-entry-modes"><button type="button" data-account-mode="login" aria-pressed="'+(accountMode==='login')+'">התחברות</button><button type="button" data-account-mode="register" aria-pressed="'+(accountMode==='register')+'">הרשמה</button></div><form id="account-auth-form">'+(accountMode==='register'?'<label>כתובת מייל<input name="email" type="email" required maxlength="254" autocomplete="email" dir="ltr" placeholder="name@example.com"></label>':'<label>מייל או שם משתמש<input name="username" required maxlength="254" autocomplete="username" dir="auto" placeholder="כתובת מייל או שם משתמש קיים"></label>')+'<label>סיסמה<input name="password" type="password" required minlength="10" maxlength="128" autocomplete="'+(accountMode==='register'?'new-password':'current-password')+'" placeholder="לפחות 10 תווים"></label>'+(accountMode==='register'?'<label>הקלדת סיסמה שוב<input name="confirmPassword" type="password" required minlength="10" maxlength="128" autocomplete="new-password"></label><p class="muted">החשבון החדש מתחיל ריק. נתוני ההדגמה והעריכות ללא חשבון לא יועתקו אליו אוטומטית.</p>':'<p class="muted">ההתחברות תטען את הנתונים מהחשבון ותחליף את נתוני ההדגמה שמוצגים כרגע. לפני התחברות, הורידו רשימות שחשוב לשמור.</p>')+'<button type="submit" class="primary">'+(accountMode==='register'?'יצירת חשבון':'כניסה לחשבון')+'</button><p id="account-form-status" class="muted" role="status"></p></form><button type="button" class="secondary device-login-button" id="account-device-login">כניסה עם זיהוי המכשיר · Face ID</button><p class="muted" id="device-auth-status" role="status">להפעלה ראשונה התחברו עם סיסמה והוסיפו מפתח גישה בחשבון.</p><p class="muted">כרגע החשבונות פועלים בשרת המקומי בלבד. שחזור סיסמה במייל עדיין אינו זמין.</p>';}
function openAccountDialog(){profileDialog.innerHTML=accountDialogContents();if(!profileDialog.open)profileDialog.showModal();refreshDeviceAuthStatus();}
document.addEventListener('submit',async e=>{if(e.target.id!=='account-auth-form')return;e.preventDefault();const form=new FormData(e.target),username=String(form.get('username')||'').trim(),password=String(form.get('password')||'');if(accountMode==='register'&&password!==form.get('confirmPassword')){$('#account-form-status').textContent='הסיסמאות אינן תואמות';return;}const button=e.target.querySelector('button[type=submit]');button.disabled=true;$('#account-form-status').textContent='מתחבר לשרת…';try{const result=await accountApi(accountMode==='register'?'/api/register':'/api/login',{method:'POST',data:{username,password,email:String(form.get('email')||'')}});await loadAccountData(result.user);profileDialog.close();toast('התחברתם לחשבון '+result.user.username);}catch(error){$('#account-form-status').textContent=error.message;}finally{button.disabled=false;}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.accountMode){accountMode=b.dataset.accountMode;openAccountDialog();}if(b.id==='account-save-now'){const ok=await saveAccountNow();$('#account-form-status').textContent=ok?'הנתונים נשמרו בחשבון':'השמירה לא הושלמה. בדקו את חיווי השמירה בראש המסך.';}if(b.id==='account-reload'){if(!window.confirm('טעינת החשבון תחליף שינויים שלא נשמרו בחלון הזה. להמשיך?'))return;try{await loadAccountData(accountUser);profileDialog.close();}catch(error){$('#account-form-status').textContent=error.message;}}if(b.id==='account-logout'){if(accountSaving){$('#account-form-status').textContent='השמירה מתבצעת. המתינו לסיומה ונסו שוב.';return;}if(!await saveAccountNow()){$('#account-form-status').textContent='לא ניתן לצאת לפני שמירה. הנתונים נשארו בחלון; בדקו את חיווי השמירה.';return;}try{await accountApi('/api/logout',{method:'POST',data:{}});accountGeneration++;accountUser=null;localEmailProfile=null;clearTimeout(accountSaveTimer);restoreAccountSnapshot(emptyAccountSnapshot());$('#open-email-profile').textContent='התחברות / הרשמה';accountStatus('אינכם מחוברים · הנתונים אינם נשמרים בחשבון');profileDialog.close();}catch(error){$('#account-form-status').textContent=error.message;}}});
for(const type of ['input','change','submit','click'])document.addEventListener(type,()=>queueAccountSave());
async function initializeAccount(){if(typeof fetch!=='function')return;accountRestoring=true;$('#content').inert=true;try{const result=await accountApi('/api/account');if(result.user)await loadAccountData(result.user);else accountStatus('התחברו כדי לשמור את הנתונים בחשבון');}catch{accountStatus('שירות החשבונות לא זמין · נתונים בחלון בלבד');}finally{accountRestoring=false;$('#content').inert=false;}}

function deviceAuthEnrollmentMarkup(){return '<section class="device-auth-setup"><h3>כניסה עם זיהוי המכשיר</h3><p class="muted">הפעלת Passkey מאפשרת אישור דרך Face ID, טביעת אצבע, Windows Hello או קוד המכשיר, לפי הגדרותיו. האפליקציה אינה מקבלת תמונות פנים או נתונים ביומטריים.</p><label class="sharing-preview-label" for="passkey-confirm-password">אישור הסיסמה להפעלה<input id="passkey-confirm-password" type="password" autocomplete="current-password" minlength="10" maxlength="128"></label><button type="button" class="secondary" id="account-device-register">הפעלת זיהוי המכשיר לחשבון</button><p id="device-auth-status" class="muted" role="status"></p><small>מפתח הגישה קשור לכתובת האתר. מפתח שנרשם ב־localhost לא יעבור אוטומטית לכתובת עתידית.</small></section>';}
async function refreshDeviceAuthStatus(){const status=$('#device-auth-status');if(!status)return;const supported=typeof window!=='undefined'&&window.isSecureContext&&typeof PublicKeyCredential!=='undefined'&&navigator.credentials;if(!supported){status.textContent='זיהוי המכשיר אינו נתמך בדפדפן או בכתובת הנוכחיים. אפשר להיכנס עם סיסמה.';const button=$('#account-device-login')||$('#account-device-register');if(button)button.disabled=true;return;}if(accountUser){try{const result=await accountApi('/api/passkeys/status');status.textContent=result.count?'לחשבון רשומים '+result.count+' מפתחות גישה. ניתן להוסיף את המכשיר הזה.':'אין עדיין מפתח גישה לחשבון. הפעילו אותו במכשיר שתומך בזיהוי.';}catch(error){status.textContent=error.message;}}}
function fromBase64URL(value){const decoded=atob(value.replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(decoded,c=>c.charCodeAt(0));}
function toBase64URL(buffer){let value='';for(const byte of new Uint8Array(buffer))value+=String.fromCharCode(byte);return btoa(value).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
function creationOptions(options){return {...options,challenge:fromBase64URL(options.challenge),user:{...options.user,id:fromBase64URL(options.user.id)},excludeCredentials:(options.excludeCredentials||[]).map(c=>({...c,id:fromBase64URL(c.id)}))};}
function authenticationOptions(options){return {...options,challenge:fromBase64URL(options.challenge),...(options.allowCredentials?{allowCredentials:options.allowCredentials.map(c=>({...c,id:fromBase64URL(c.id)}))}:{})};}
function deviceCredentialJSON(credential,register){return {id:credential.id,rawId:toBase64URL(credential.rawId),type:credential.type,authenticatorAttachment:credential.authenticatorAttachment,clientExtensionResults:credential.getClientExtensionResults(),response:register?{clientDataJSON:toBase64URL(credential.response.clientDataJSON),attestationObject:toBase64URL(credential.response.attestationObject),transports:credential.response.getTransports?.()||[]}:{clientDataJSON:toBase64URL(credential.response.clientDataJSON),authenticatorData:toBase64URL(credential.response.authenticatorData),signature:toBase64URL(credential.response.signature),userHandle:credential.response.userHandle?toBase64URL(credential.response.userHandle):null}};}
async function useDeviceAuth(register,button){const status=$('#device-auth-status');if(typeof PublicKeyCredential==='undefined'||!navigator.credentials){status.textContent='זיהוי המכשיר אינו נתמך כאן. השתמשו בסיסמה.';return;}button.disabled=true;status.textContent='ממתין לאישור דרך המכשיר…';try{const password=register?$('#passkey-confirm-password').value:'';if(register&&password.length<10)throw Error('הקלידו את הסיסמה הנוכחית לאישור ההפעלה');const route=register?'register':'login',flow=await accountApi('/api/passkeys/'+route+'/options',{method:'POST',data:register?{password}:{}});if(register)$('#passkey-confirm-password').value='';const credential=register?await navigator.credentials.create({publicKey:creationOptions(flow.options)}):await navigator.credentials.get({publicKey:authenticationOptions(flow.options)});if(!credential)throw Error('הזיהוי לא הושלם');const result=await accountApi('/api/passkeys/'+route+'/verify',{method:'POST',data:{flowId:flow.flowId,response:deviceCredentialJSON(credential,register)}});if(register){status.textContent='זיהוי המכשיר הופעל. אפשר להשתמש בו בכניסה הבאה.';}else{await loadAccountData(result.user);profileDialog.close();toast('התחברתם באמצעות זיהוי המכשיר');}}catch(error){status.textContent=error.name==='NotAllowedError'?'אישור המכשיר בוטל או לא הושלם. אפשר לנסות שוב או להיכנס עם סיסמה.':error.name==='InvalidStateError'?'ייתכן שכבר קיים מפתח גישה לחשבון במכשיר הזה.':error.message;}finally{button.disabled=false;}}
document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.id==='account-device-register')useDeviceAuth(true,button);if(button.id==='account-device-login')useDeviceAuth(false,button);});
document.addEventListener('input',e=>{if(e.target.id==='venue-directory-search'){venueSearch=e.target.value;render();}});document.addEventListener('change',e=>{if(e.target.id==='include-demo-venues'){includeDemoVenues=e.target.checked;render();}});
function giftValueText(gift){return gift.kind==='item'?'מתנה: '+(gift.description||'ללא תיאור'):nis(gift.amount);}
function updateGiftKind(){const item=$('#gift-kind').value==='item';$('#gift-money-field').hidden=item;$('#gift-item-field').hidden=!item;$('#gift-form [name=amount]').disabled=item;$('#gift-form [name=amount]').required=!item;$('#gift-form [name=description]').disabled=!item;$('#gift-form [name=description]').required=item;}
document.addEventListener('change',e=>{if(e.target.id==='gift-kind')updateGiftKind();});
navigate('home');
$('#open-email-profile').hidden=true;$('#account-save-status').hidden=true;


const invitationRsvpDialog=document.createElement('dialog');invitationRsvpDialog.setAttribute('aria-label','אישור הגעה להזמנה');document.body.appendChild(invitationRsvpDialog);
function invitationRsvpOptions(){return ['אישרו',...(active().type==='חתונה'?['מגיעים רק לחופה']:[]),'לא מגיעים'];}
function invitationRsvpContents(){return '<div class="dialog-top"><h2>אישור הגעה</h2><button type="button" class="close" aria-label="סגירה">×</button></div><p>'+esc(active().name)+'</p><fieldset class="rsvp-invitation-choices"><legend>נשמח לדעת אם תגיעו</legend>'+invitationRsvpOptions().map((status,i)=>'<label><input type="radio" name="invitation-response" value="'+esc(status)+'"> '+(status==='אישרו'?'מגיעים לחגוג':esc(status))+(status==='מגיעים רק לחופה'?'<small>ללא הושבה לארוחה</small>':'')+'</label>').join('')+'</fieldset><label id="invitation-rsvp-count-label" for="invitation-rsvp-count">כמה משתתפים מגיעים? כולל אתכם<input id="invitation-rsvp-count" name="count" type="number" inputmode="numeric" min="1" max="100" step="1" value="1" required></label><p class="muted">תצוגה מקדימה בלבד — הבחירה כאן אינה שולחת תשובה ואינה מעדכנת מוזמן. שליחת אישורי הגעה אמיתיים תתווסף בהמשך.</p>';}
document.addEventListener('click',e=>{if(!e.target.closest('#preview-rsvp'))return;invitationRsvpDialog.innerHTML=invitationRsvpContents();invitationRsvpDialog.showModal();});

document.addEventListener('change',e=>{if(e.target.name!=='invitation-response')return;const absent=e.target.value==='לא מגיעים',count=$('#invitation-rsvp-count');count.disabled=absent;count.required=!absent;$('#invitation-rsvp-count-label').hidden=absent;});


function customerDefaultPositions(capacities,previous={}){const ids=Object.keys(capacities),cols=Math.max(1,Math.ceil(Math.sqrt(ids.length*1.5))),rows=Math.ceil(ids.length/cols);return Object.fromEntries(ids.map((id,i)=>{const old=previous?.[id];return [id,{x:Number.isFinite(old?.x)?Math.max(6,Math.min(94,old.x)):((i%cols)+.5)*100/cols,y:Number.isFinite(old?.y)?Math.max(8,Math.min(92,old.y)):(Math.floor(i/cols)+.5)*100/rows}];}));}
function customerPlanMap(editable){const pass=customerSeatingPass();if(!pass?.capacities)return '';const positions=customerDefaultPositions(pass.capacities,editable?pass.layoutDraft||pass.positions:pass.positions);if(editable)pass.layoutDraft=positions;return '<div class="customer-layout-map '+(editable?'is-editing':'is-saved')+'" role="group" aria-label="'+(editable?'עריכת מיקום שולחנות':'מפת שולחנות לשיבוץ')+'">'+(pass.imageUrl?'<img class="customer-layout-background" src="'+esc(pass.imageUrl)+'" alt="סקיצת רקע">':'<span class="customer-layout-stage">במה / רחבת ריקודים</span>')+Object.entries(pass.capacities).map(([id,capacity])=>'<button type="button" class="customer-layout-table" '+(editable?'data-layout-drag="'+id+'"':'data-table="'+id+'"')+' style="left:'+positions[id].x+'%;top:'+positions[id].y+'%" aria-label="שולחן '+id+', '+capacity+' מקומות'+(editable?', גרירה או מקשי חצים':'')+'"><strong>'+id+'</strong><span>'+ (editable?capacity+' מקומות':occupancy(Number(id))+' / '+capacity)+'</span></button>').join('')+'</div>';}
function moveCustomerTable(pass,id,x,y){if(!pass?.editingLayout||!pass.capacities?.[id])return false;pass.layoutDraft??=customerDefaultPositions(pass.capacities,pass.positions);pass.layoutDraft[id]={x:Math.max(6,Math.min(94,x)),y:Math.max(8,Math.min(92,y))};return true;}
document.addEventListener('click',e=>{if(e.target.closest('#customer-manual-plan')){const pass=customerSeatingPass();if(!pass?.demoPaid)return;pass.manualPlan=true;render();}if(e.target.closest('#edit-customer-layout')){const pass=customerSeatingPass();if(!pass?.demoPaid||!pass.capacities)return;pass.editingLayout=true;pass.layoutDraft=customerDefaultPositions(pass.capacities,pass.positions);autoSeatUndo=null;navigate('seatingPurchase');}});
let customerTableDrag=null;
document.addEventListener('pointerdown',e=>{const button=e.target.closest('[data-layout-drag]'),pass=customerSeatingPass();if(!button||!pass?.demoPaid||!pass.editingLayout)return;const map=button.closest('.customer-layout-map');if(!map)return;e.preventDefault();button.setPointerCapture(e.pointerId);customerTableDrag={button,map,pass,event:activeEvent,id:button.dataset.layoutDrag,pointer:e.pointerId};});
document.addEventListener('pointermove',e=>{const drag=customerTableDrag;if(!drag||drag.pointer!==e.pointerId||drag.event!==activeEvent||customerSeatingPass()!==drag.pass)return;const rect=drag.map.getBoundingClientRect();if(!rect.width||!rect.height)return;if(moveCustomerTable(drag.pass,drag.id,(e.clientX-rect.left)*100/rect.width,(e.clientY-rect.top)*100/rect.height)){const point=drag.pass.layoutDraft[drag.id];drag.button.style.left=point.x+'%';drag.button.style.top=point.y+'%';}});
for(const type of ['pointerup','pointercancel'])document.addEventListener(type,e=>{if(customerTableDrag?.pointer===e.pointerId)customerTableDrag=null;});
document.addEventListener('keydown',e=>{const button=e.target.closest('[data-layout-drag]');if(!button||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;const pass=customerSeatingPass();if(!pass?.demoPaid||!pass.editingLayout)return;e.preventDefault();const id=button.dataset.layoutDrag,point=pass.layoutDraft?.[id]||customerDefaultPositions(pass.capacities,pass.positions)[id],step=e.shiftKey?5:1;if(moveCustomerTable(pass,id,point.x+(e.key==='ArrowRight'?step:e.key==='ArrowLeft'?-step:0),point.y+(e.key==='ArrowDown'?step:e.key==='ArrowUp'?-step:0))){button.style.left=pass.layoutDraft[id].x+'%';button.style.top=pass.layoutDraft[id].y+'%';}});

function eventToolIcon(view,fallback=''){const icons={"eventGifts":"<svg class=\"gift-envelope-icon\" viewBox=\"0 0 40 40\" width=\"36\" height=\"36\" fill=\"none\" aria-hidden=\"true\"><rect x=\"5\" y=\"10\" width=\"30\" height=\"21\" rx=\"2.5\" fill=\"currentColor\" fill-opacity=\".07\" stroke=\"currentColor\" stroke-width=\"1.5\"/><path d=\"m6 12 14 11 14-11M6 29l10-9m18 9-10-9\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>","venue":"<svg class=\"estate-icon\" viewBox=\"0 0 44 40\" width=\"38\" height=\"36\" fill=\"none\" aria-hidden=\"true\"><path d=\"M4 35V18h10v17M30 35V18h10v17M14 35V13h16v22\" fill=\"currentColor\" fill-opacity=\".08\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linejoin=\"round\"/><path d=\"m11 13 11-8 11 8H11ZM2 18l7-5 5 4m16 0 5-4 7 5M2 35h40M18 35V25a4 4 0 0 1 8 0v10\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M19 16h6v4h-6zM7 22h3v4H7zM7 29h3v3H7zM34 22h3v4h-3zM34 29h3v3h-3z\" fill=\"currentColor\" fill-opacity=\".2\" stroke=\"currentColor\" stroke-width=\"1.1\"/><path d=\"M17 8V4h3M22 2v3M22 26v9\" stroke=\"currentColor\" stroke-width=\"1.2\" stroke-linecap=\"round\"/></svg>","seating":"<svg class=\"round-table-icon\" viewBox=\"0 0 40 40\" width=\"36\" height=\"36\" fill=\"none\" aria-hidden=\"true\"><rect x=\"17\" y=\"2\" width=\"6\" height=\"5\" rx=\"1.5\" transform=\"rotate(0 20 20)\" fill=\"currentColor\" fill-opacity=\".12\" stroke=\"currentColor\" stroke-width=\"1.2\"/><rect x=\"17\" y=\"2\" width=\"6\" height=\"5\" rx=\"1.5\" transform=\"rotate(45 20 20)\" fill=\"currentColor\" fill-opacity=\".12\" stroke=\"currentColor\" stroke-width=\"1.2\"/><rect x=\"17\" y=\"2\" width=\"6\" height=\"5\" rx=\"1.5\" transform=\"rotate(90 20 20)\" fill=\"currentColor\" fill-opacity=\".12\" stroke=\"currentColor\" stroke-width=\"1.2\"/><rect x=\"17\" y=\"2\" width=\"6\" height=\"5\" rx=\"1.5\" transform=\"rotate(135 20 20)\" fill=\"currentColor\" fill-opacity=\".12\" stroke=\"currentColor\" stroke-width=\"1.2\"/><rect x=\"17\" y=\"2\" width=\"6\" height=\"5\" rx=\"1.5\" transform=\"rotate(180 20 20)\" fill=\"currentColor\" fill-opacity=\".12\" stroke=\"currentColor\" stroke-width=\"1.2\"/><rect x=\"17\" y=\"2\" width=\"6\" height=\"5\" rx=\"1.5\" transform=\"rotate(225 20 20)\" fill=\"currentColor\" fill-opacity=\".12\" stroke=\"currentColor\" stroke-width=\"1.2\"/><rect x=\"17\" y=\"2\" width=\"6\" height=\"5\" rx=\"1.5\" transform=\"rotate(270 20 20)\" fill=\"currentColor\" fill-opacity=\".12\" stroke=\"currentColor\" stroke-width=\"1.2\"/><rect x=\"17\" y=\"2\" width=\"6\" height=\"5\" rx=\"1.5\" transform=\"rotate(315 20 20)\" fill=\"currentColor\" fill-opacity=\".12\" stroke=\"currentColor\" stroke-width=\"1.2\"/><circle cx=\"20\" cy=\"20\" r=\"10\" fill=\"currentColor\" fill-opacity=\".07\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"20\" cy=\"20\" r=\"1.5\" fill=\"currentColor\" fill-opacity=\".35\"/></svg>"};return icons[view]||esc(fallback);}
